def create_opening_cost_layers(apps, schema_editor):
    CostLayer = apps.get_model('inventory', 'InventoryCostLayer')
    Product = apps.get_model('products', 'Product')
    StockItem = apps.get_model('inventory', 'StockItem')
    database = schema_editor.connection.alias
    now = django.utils.timezone.now()

    for product in Product.objects.using(database).all().iterator():
        cost = product.cost_price if product.cost_price and product.cost_price > 0 else None
        stocked_units = 0
        for stock in StockItem.objects.using(database).filter(product_id=product.pk).iterator():
            if stock.quantity <= 0:
                continue
            stocked_units += stock.quantity
            CostLayer.objects.using(database).create(
                product_id=product.pk,
                location_id=stock.location_id,
                source='opening',
                reference=f'OPENING-{product.pk}-{stock.location_id}',
                received_at=now,
                quantity_received=stock.quantity,
                quantity_remaining=stock.quantity,
                unit_cost=cost,
            )

        unlocated_units = max((product.quantity or 0) - stocked_units, 0)
        if unlocated_units:
            CostLayer.objects.using(database).create(
                product_id=product.pk,
                location=None,
                source='opening',
                reference=f'OPENING-{product.pk}-GLOBAL',
                received_at=now,
                quantity_received=unlocated_units,
                quantity_remaining=unlocated_units,
                unit_cost=cost,
            )


